/// One-shot latch so exactly one of {RPC response, timeout} runs a completion.
private final class CompletionGuard: @unchecked Sendable {
    private let lock = NSLock()
    private var finished = false
    func tryFinish() -> Bool {
        lock.lock()
        defer { lock.unlock() }
        if finished { return false }
        finished = true
        return true
    }
}

