16	type pushMessage struct {
17		Type string `json:"type"`
18		Data any    `json:"data"`
19	}
20	
21	type commandRequest struct {
22		ID     string         `json:"id"`
23		Method string         `json:"method"`
24		Params map[string]any `json:"params"`
25	}
26	
27	type commandResponse struct {
28		ID     string          `json:"id"`
29		OK     bool            `json:"ok"`
30		Result json.RawMessage `json:"result,omitempty"`
31		Error  *rpcError       `json:"error,omitempty"`
32	}
