31	// Render returns the rendered transcript for a surface's resume_binding.
32	//
33	// supported reports whether the binding describes a Claude surface at all.
34	// If supported is true but text is empty (""), no transcript file was found yet.
35	// sessionID is the base filename (without .jsonl) of the active transcript.
36	func (r *Resolver) Render(resumeBinding map[string]any, maxMessages int) (text string, supported bool, sessionID string, err error) {
37		if resumeBinding == nil {
38			return "", false, "", nil
39		}
40		kind, _ := resumeBinding["kind"].(string)
41		if kind != "claude" {
42			return "", false, "", nil
43		}
44	
45		projectDir, err := r.resolveProjectDir(resumeBinding)
46		if err != nil {
47			return "", true, "", err
48		}
49		if projectDir == "" {
50			// Claude surface but no transcript directory yet.
51			return "", true, "", nil
52		}
53	
54		transcriptPath, err := latestJSONL(projectDir)
55		if err != nil {
56			return "", true, "", err
57		}
58		if transcriptPath == "" {
59			return "", true, "", nil
60		}
61	
62		sessionID = strings.TrimSuffix(filepath.Base(transcriptPath), ".jsonl")
63	
64		info, err := os.Stat(transcriptPath)
65		if err != nil {
66			return "", true, sessionID, err
67		}
68	
69		// Check cache.
70		if v, ok := r.cache.Load(transcriptPath); ok {
71			entry := v.(*cacheEntry)
72			if entry.modTime.Equal(info.ModTime()) && entry.size == info.Size() {
73				return entry.text, true, sessionID, nil
74			}
75		}
76	
77		data, err := os.ReadFile(transcriptPath)
78		if err != nil {
79			return "", true, sessionID, err
80		}
81	
82		rendered := renderJSONL(data, maxMessages)
83		r.cache.Store(transcriptPath, &cacheEntry{
84			modTime: info.ModTime(),
85			size:    info.Size(),
86			text:    rendered,
87		})
