128	// latestJSONL returns the most-recently-modified *.jsonl file in dir, or "".
129	func latestJSONL(dir string) (string, error) {
130		entries, err := os.ReadDir(dir)
131		if err != nil {
132			return "", err
133		}
134	
135		var bestPath string
136		var bestMod time.Time
137	
138		for _, e := range entries {
139			if e.IsDir() || !strings.HasSuffix(e.Name(), ".jsonl") {
140				continue
141			}
142			full := filepath.Join(dir, e.Name())
143			info, err := e.Info()
144			if err != nil {
145				continue
146			}
147			if bestPath == "" || info.ModTime().After(bestMod) {
148				bestPath = full
149				bestMod = info.ModTime()
150			}
151		}
152		return bestPath, nil
153	}
